content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;
  color-scheme: light dark;
}

body {
  margin: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 320px;
  min-height: 100vh;
  transition: background-color 0.3s ease, color 0.3s ease;
}

* {
  box-sizing: border-box;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  width: 100vw;
  padding: 20px;
  transition: background-color 0.3s ease, color 0.3s ease;
}

.header {
  margin-bottom: 24px;
  text-align: center;
}

.title {
  font-size: 1.8rem;
  font-weight: 700;
  margin: 0;
}

.clock-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  margin-bottom: 30px;
}

.clock-face {
  position: relative;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
  transition: background-color 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease;
}

.hand {
  position: absolute;
  bottom: 50%;
  left: 50%;
  transform-origin: bottom center;
  border-radius: 4px;
  z-index: 2;
  transition: background-color 0.3s ease;
}

.hour-hand {
  width: 6px;
  height: 70px;
  transform: translateX(-50%);
}

.minute-hand {
  width: 4px;
  height: 100px;
  transform: translateX(-50%);
}

.second-hand {
  width: 2px;
  height: 110px;
  background-color: #ff3b30;
  transform: translateX(-50%);
  z-index: 3;
}

.center-dot {
  position: absolute;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  z-index: 4;
  transform: translate(-50%, -50%);
  top: 50%;
  left: 50%;
  transition: background-color 0.3s ease;
}

.marker {
  position: absolute;
  width: 2px;
  height: 10px;
  top: 10px;
  left: calc(50% - 1px);
  transform-origin: center 130px;
  transition: background-color 0.3s ease;
}

.digital-time {
  font-size: 1.5rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: 1px;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
  max-width: 400px;
}

.btn {
  padding: 8px 16px;
  font-size: 0.9rem;
  font-weight: 500;
  border-radius: 6px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover {
  opacity: 0.85;
}

/* Theme: Classic */
.theme-classic {
  background-color: #f5f2eb;
  color: #1a1a1a;
}
.theme-classic .clock-face {
  background-color: #fffdf9;
  border: 8px solid #8b5a2b;
}
.theme-classic .hour-hand,
.theme-classic .minute-hand {
  background-color: #1a1a1a;
}
.theme-classic .center-dot {
  background-color: #8b5a2b;
}
.theme-classic .marker {
  background-color: #b5a48f;
}
.theme-classic .btn {
  background-color: #e6dfd1;
  color: #1a1a1a;
  border-color: #d1c7b7;
}
.theme-classic .btn-active {
  background-color: #8b5a2b;
  color: #ffffff;
  border-color: #5c3b1c;
}

/* Theme: Modern */
.theme-modern {
  background-color: #f0f4f8;
  color: #0b1d2e;
}
.theme-modern .clock-face {
  background-color: #ffffff;
  border: 2px solid #bcccdc;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
}
.theme-modern .hour-hand,
.theme-modern .minute-hand {
  background-color: #243b53;
}
.theme-modern .center-dot {
  background-color: #0056b3;
}
.theme-modern .marker {
  background-color: #829ab1;
}
.theme-modern .btn {
  background-color: #d9e2ec;
  color: #0b1d2e;
  border: none;
}
.theme-modern .btn-active {
  background-color: #0056b3;
  color: #ffffff;
}

/* Theme: Dark */
.theme-dark {
  background-color: #0d0d0d;
  color: #f1f1f1;
}
.theme-dark .clock-face {
  background-color: #1a1a1a;
  border: 4px solid #2c2c2c;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.7);
}
.theme-dark .hour-hand,
.theme-dark .minute-hand {
  background-color: #f1f1f1;
}
.theme-dark .center-dot {
  background-color: #ce93d8;
}
.theme-dark .marker {
  background-color: #555555;
}
.theme-dark .btn {
  background-color: #252525;
  color: #f1f1f1;
  border: 1px solid #3d3d3d;
}
.theme-dark .btn-active {
  background-color: #ce93d8;
  color: #0d0d0d;
  border-color: #ce93d8;
  font-weight: 600;
}

/* Responsive Styles */
@media (max-width: 480px) {
  .app-container {
    padding: 10px;
  }

  .clock-face {
    width: 240px;
    height: 240px;
  }

  .marker {
    transform-origin: center 110px;
  }

  .hour-hand {
    height: 55px;
  }

  .minute-hand {
    height: 85px;
  }

  .second-hand {
    height: 95px;
  }

  .title {
    font-size: 1.5rem;
  }

  .digital-time {
    font-size: 1.3rem;
  }

  .controls {
    max-width: 300px;
  }

  .btn {
    padding: 6px 12px;
    font-size: 0.85rem;
  }
}

export interface ClockSettings {
  showSeconds: boolean;
  is24Hour: boolean;
  theme: 'classic' | 'modern' | 'dark';
}

export interface TimeInfo {
  hours: number;
  minutes: number;
  seconds: number;
}

import { useState, useEffect } from 'react'
import './index.css'
import { ClockSettings, TimeInfo } from './types'
import ClockFace from './ClockFace'
import ClockControls from './ClockControls'

export default function App() {
  const [settings, setSettings] = useState<ClockSettings>(() => {
    const saved = localStorage.getItem('clock_settings')
    if (saved) {
      try {
        return JSON.parse(saved)
      } catch (e) {
        console.error('Failed to parse saved clock settings:', e)
      }
    }
    return {
      showSeconds: true,
      is24Hour: false,
      theme: 'modern',
    }
  })

  const [time, setTime] = useState<TimeInfo>({
    hours: new Date().getHours(),
    minutes: new Date().getMinutes(),
    seconds: new Date().getSeconds(),
  })

  useEffect(() => {
    localStorage.setItem('clock_settings', JSON.stringify(settings))
  }, [settings])

  useEffect(() => {
    const updateTime = () => {
      const now = new Date()
      setTime({
        hours: now.getHours(),
        minutes: now.getMinutes(),
        seconds: now.getSeconds(),
      })
    }

    // 初回レンダリング時の時間セット
    updateTime()

    // 次の秒の変わり目までのミリ秒を計算してズレを防止
    const now = new Date()
    const msUntilNextSecond = 1000 - now.getMilliseconds()

    let intervalId: ReturnType<typeof setInterval>

    const timeoutId = setTimeout(() => {
      updateTime()
      intervalId = setInterval(updateTime, 1000)
    }, msUntilNextSecond)

    return () => {
      clearTimeout(timeoutId)
      if (intervalId) {
        clearInterval(intervalId)
      }
    }
  }, [])

  const handleUpdateSettings = (newSettings: ClockSettings) => {
    setSettings(newSettings)
  }

  return (
    <div className={`app-container theme-${settings.theme}`}>
      <header className="header">
        <h1 className="title">アナログ時計</h1>
      </header>
      <ClockFace time={time} settings={settings} />
      <ClockControls settings={settings} onUpdateSettings={handleUpdateSettings} />
    </div>
  )
}

import './index.css'
import { ClockSettings, TimeInfo } from './types'

interface ClockFaceProps {
  time: TimeInfo
  settings: ClockSettings
}

export default function ClockFace({ time, settings }: ClockFaceProps) {
  const { hours, minutes, seconds } = time
  const { showSeconds, is24Hour } = settings

  const secondDegrees = seconds * 6
  const minuteDegrees = minutes * 6 + seconds * 0.1
  const hourDegrees = ((hours % 12) + minutes / 60) * 30

  const displayHours = is24Hour ? hours : hours % 12 || 12
  const formattedHours = String(displayHours).padStart(2, '0')
  const formattedMinutes = String(minutes).padStart(2, '0')
  const formattedSeconds = String(seconds).padStart(2, '0')
  const ampm = !is24Hour ? (hours >= 12 ? ' PM' : ' AM') : ''

  const markers = Array.from({ length: 12 }, (_, i) => {
    const angle = i * 30
    const isMajor = i % 3 === 0
    return (
      <div
        key={i}
        className="marker"
        style={{
          transform: `rotate(${angle}deg)`,
          ...(isMajor
            ? {
                width: '4px',
                height: '14px',
                left: 'calc(50% - 2px)',
                opacity: 0.9,
              }
            : {}),
        }}
      />
    )
  })

  return (
    <div className="clock-wrapper" role="region" aria-label="時計表示エリア">
      <div
        className="clock-face"
        role="timer"
        aria-label={`アナログ時計: ${formattedHours}時${formattedMinutes}分${showSeconds ? `${formattedSeconds}秒` : ''}${ampm}`}
      >
        {markers}
        <div
          className="hand hour-hand"
          style={{ transform: `translateX(-50%) rotate(${hourDegrees}deg)` }}
          aria-hidden="true"
        />
        <div
          className="hand minute-hand"
          style={{ transform: `translateX(-50%) rotate(${minuteDegrees}deg)` }}
          aria-hidden="true"
        />
        {showSeconds && (
          <div
            className="hand second-hand"
            style={{ transform: `translateX(-50%) rotate(${secondDegrees}deg)` }}
            aria-hidden="true"
          />
        )}
        <div className="center-dot" aria-hidden="true" />
      </div>

      <div
        className="digital-time"
        aria-label={`デジタル時計: ${formattedHours}:${formattedMinutes}${showSeconds ? `:${formattedSeconds}` : ''}${ampm}`}
      >
        {formattedHours}:{formattedMinutes}
        {showSeconds ? `:${formattedSeconds}` : ''}
        {ampm}
      </div>
    </div>
  )
}

import './index.css'
import { ClockSettings } from './types'

interface ClockControlsProps {
  settings: ClockSettings
  onUpdateSettings: (newSettings: ClockSettings) => void
}

export default function ClockControls({
  settings,
  onUpdateSettings,
}: ClockControlsProps) {
  const { showSeconds, is24Hour, theme } = settings

  const toggleSeconds = () => {
    onUpdateSettings({ ...settings, showSeconds: !showSeconds })
  }

  const toggleFormat = () => {
    onUpdateSettings({ ...settings, is24Hour: !is24Hour })
  }

  const changeTheme = (newTheme: ClockSettings['theme']) => {
    onUpdateSettings({ ...settings, theme: newTheme })
  }

  return (
    <div className="controls" role="group" aria-label="時計のコントロールパネル">
      <button
        className={`btn ${showSeconds ? 'btn-active' : ''}`}
        onClick={toggleSeconds}
        style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}
        aria-pressed={showSeconds}
      >
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <circle cx="12" cy="12" r="10"></circle>
          <polyline points="12 6 12 12 16 14"></polyline>
        </svg>
        {showSeconds ? '秒針を隠す' : '秒針を表示'}
      </button>

      <button
        className={`btn ${is24Hour ? 'btn-active' : ''}`}
        onClick={toggleFormat}
        style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}
        aria-pressed={is24Hour}
      >
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M21 12a9 9 0 1 1-9-9c2.52 0 4.93 1 6.74 2.74L21 8"></path>
          <polyline points="21 3 21 8 16 8"></polyline>
        </svg>
        {is24Hour ? '12時間表示' : '24時間表示'}
      </button>

      <button
        className={`btn ${theme === 'modern' ? 'btn-active' : ''}`}
        onClick={() => changeTheme('modern')}
        style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}
        aria-pressed={theme === 'modern'}
      >
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <rect x="2" y="3" width="20" height="14" rx="2" ry="2"></rect>
          <line x1="8" y1="21" x2="16" y2="21"></line>
          <line x1="12" y1="17" x2="12" y2="21"></line>
        </svg>
        モダン
      </button>

      <button
        className={`btn ${theme === 'classic' ? 'btn-active' : ''}`}
        onClick={() => changeTheme('classic')}
        style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}
        aria-pressed={theme === 'classic'}
      >
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M4 19.5v-15A2.5 2.5 0 0 1 6.5 2H20v20H6.5a2.5 2.5 0 0 1-2.5-2.5Z"></path>
          <path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"></path>
        </svg>
        クラシック
      </button>

      <button
        className={`btn ${theme === 'dark' ? 'btn-active' : ''}`}
        onClick={() => changeTheme('dark')}
        style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}
        aria-pressed={theme === 'dark'}
      >
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path>
        </svg>
        ダーク
      </button>
    </div>
  )
}
